examples.code:
// Table: Orders, partition key: customerId, sort key: orderSortKey
{
  "customerId": "CUST#48213",
  "orderSortKey": "ORDER#2026-08-01#O-9911",
  "status": "shipped",
  "total": 129.50,
  "items": [{"sku": "WIDGET-1", "qty": 2}]
}

// A Query for this customer's orders in August 2026, sorted chronologically:
// KeyConditionExpression: customerId = :cid AND begins_with(orderSortKey, :prefix)
// :cid = "CUST#48213", :prefix = "ORDER#2026-08"

// FAST: uses the partition key directly, routed to exactly one partition
Query:
  KeyConditionExpression: customerId = :cid
  :cid = "CUST#48213"
// -> reads only this customer's items, cost independent of total table size

// SLOW: no partition key involved, has to examine items broadly
Scan:
  FilterExpression: total > :amount
  :amount = 100
// -> reads through a large portion of the table's items to evaluate the filter,
//    cost grows with total table size regardless of how few items actually match

